const MetaclassBinding* findMetaclass(std::string_view name) {
    static const std::unordered_map<std::string_view, const MetaclassBinding*> index = [] {
        std::unordered_map<std::string_view, const MetaclassBinding*> result;
        for (const auto& binding : metaclassTable) result.emplace(binding.name, &binding);
        return result;
    }();
    const auto found = index.find(name);
    return found == index.end() ? nullptr : found->second;
}

